//! Runtime for Rust code generated by the yaffle compiler.
//!
//! Generated code refers to this crate as `yr` (`use yaffle_runtime as yr;`, or the inlined
//! copy). Modules only refer to each other through `super::`, so the crate can be inlined as a
//! module of another crate.

pub mod checksum;
pub mod codec;
pub mod error;
pub mod helpers;
pub mod int;
pub mod json;
pub mod prim;
pub mod read;
pub mod regex;
pub mod space;
pub mod strings;
pub mod view;
pub mod write;

pub use checksum::{adler32, crc32};
pub use codec::{Arg, Codec, CodecCtx, ExternType, ViaCache};
pub use error::{ErrorCode, PathSeg, Result, ResultExt, YaffleError};
pub use helpers::*;
pub use json::{JsonIn, JsonOut, Value};
pub use prim::Endian;
pub use read::{Fill, Reader, Shared, StrLen};
pub use space::{FileSource, RangedFn, Source, Space};
pub use strings::Encoding;
pub use view::{FieldSpan, Grow, Loc, Patch, Scan, ViewCtx, ViewRoot, ViewState};
pub use write::{Align, Key, LSeg, LayoutItem, PlaceOpts, PtrFormat, Resolver, Span, WFill, Writer};

/// Options for `parse_with` and `view_with`.
#[derive(Debug, Clone, Copy, Default)]
pub struct ParseOptions {
    /// Strict mode: padding fill, reserved bits and bools are checked.
    pub strict: bool,
}
